#define MAX_LEN 15
#define MAX_STATES 100000

// returns the third color
char third(char a, char b) {
    if ((a == 'r' && b == 'g') || (a == 'g' && b == 'r')) return 'b';
    if ((a == 'r' && b == 'b') || (a == 'b' && b == 'r')) return 'g';
    return 'r';
}

int main() {
    char s[MAX_LEN];
    while (1) {
        scanf("%s", s);
        if (s[0] == '0') break;

        int len = strlen(s);
        char *visited[MAX_STATES];
        int visited_count = 0;

        char *state = (char *)malloc(len + 1);
        strcpy(state, s);

        int time = 0;
        int found = 0;

        while (1) {
            // check if all same
            int all_same = 1;
            for (int i = 1; i < len; i++) {
                if (state[i] != state[0]) {
                    all_same = 0;
                    break;
                }
            }
            if (all_same) {
                printf("%d\n", time);
                found = 1;
                free(state);
                break;
            }

            // check for repeat
            int repeated = 0;
            for (int i = 0; i < visited_count; i++) {
                if (strcmp(visited[i], state) == 0) {
                    repeated = 1;
                    break;
                }
            }
            if (repeated) {
                printf("NA\n");
                free(state);
                break;
            }

            // store current state
            visited[visited_count] = (char *)malloc(len + 1);
            strcpy(visited[visited_count], state);
            visited_count++;

            // compute next state
            char *next = (char *)malloc(len + 1);
            for (int i = 0; i < len; i++) {
                if (i == 0) {
                    if (state[i] != state[i+1])
                        next[i] = third(state[i], state[i+1]);
                    else
                        next[i] = state[i];
                } else if (i == len - 1) {
                    if (state[i] != state[i-1])
                        next[i] = third(state[i], state[i-1]);
                    else
                        next[i] = state[i];
                } else {
                    if (state[i] != state[i-1])
                        next[i] = third(state[i], state[i-1]);
                    else if (state[i] != state[i+1])
                        next[i] = third(state[i], state[i+1]);
                    else
                        next[i] = state[i];
                }
            }
            next[len] = '\0';
            strcpy(state, next);
            free(next);
            time++;
        }

        // free visited states
        for (int i = 0; i < visited_count; i++) {
            free(visited[i]);
        }
    }
    return 0;
}

