int main() {
    char line[MAXLEN];
    while (scanf("%s", line) == 1 && line[0] != '0') {
        int n = strlen(line);
        // BFS
        // Use hash map or just queue with visited set
        // For small n, encode as base-3 number
        // Max n ~ 12 or so
        int maxval = 1;
        for (int i = 0; i < n; i++) maxval *= 3;
        char *visited = calloc(maxval, 1);
        int *dist = malloc(maxval * sizeof(int));
        memset(dist, -1, maxval * sizeof(int));

        int start = 0;
        for (int i = 0; i < n; i++) {
            int c = (line[i]=='r')?0:(line[i]=='g')?1:2;
            start = start*3 + c;
        }

        int *queue = malloc(maxval * sizeof(int));
        int head=0, tail=0;
        queue[tail++] = start; dist[start] = 0; visited[start] = 1;
        int ans = -1;
        while (head < tail) {
            int cur = queue[head++];
            int tmp = cur, seg[MAXLEN];
            for (int i=n-1;i>=0;i--) { seg[i]=tmp%3; tmp/=3; }
            // check uniform
            int uni=1; for(int i=1;i<n;i++) if(seg[i]!=seg[0]) {uni=0;break;}
            if (uni) { ans = dist[cur]; break; }
            // apply rule
            int nseg[MAXLEN];
            for (int i=0;i<n;i++) {
                int l = (i>0)?seg[i-1]:-1, r=(i<n-1)?seg[i+1]:-1;
                if (l==-1||r==-1) nseg[i]=seg[i];
                else if (l==r) nseg[i]=seg[i];
                else nseg[i]=(3-l-r)%3;
            }
            int nstate=0; for(int i=0;i<n;i++) nstate=nstate*3+nseg[i];
            if (!visited[nstate]) { visited[nstate]=1; dist[nstate]=dist[cur]+1; queue[tail++]=nstate; }
        }
        if (ans<0) printf("NA\n"); else printf("%d\n", ans);
        free(visited); free(dist); free(queue);
    }
}

