static int distv[MAXN][MAXN][MAXN];
static int vis[MAXN][MAXN][MAXN];

int main(void) {
    char s[40];

    while (scanf("%s", s) == 1) {
        if (strcmp(s, "0") == 0) break;

        int n = (int)strlen(s);
        int cnt[3] = {0, 0, 0};

        for (int i = 0; i < n; i++) {
            if (s[i] == 'r') cnt[0]++;
            else if (s[i] == 'g') cnt[1]++;
            else cnt[2]++;
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    distv[i][j][k] = INF;
                    vis[i][j][k] = 0;
                }
            }
        }

        distv[cnt[0]][cnt[1]][cnt[2]] = 0;

        while (1) {
            int best = INF;
            int a = -1, b = -1, c = -1;

            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    int k = n - i - j;
                    if (k < 0 || k > n) continue;
                    if (!vis[i][j][k] && distv[i][j][k] < best) {
                        best = distv[i][j][k];
                        a = i; b = j; c = k;
                    }
                }
            }

            if (a == -1) break;
            vis[a][b][c] = 1;

            if (a == n || b == n || c == n) break;

            int cur = distv[a][b][c];

            if (a > 0 && b > 0) {
                if (distv[a - 1][b - 1][c + 2] > cur + 1)
                    distv[a - 1][b - 1][c + 2] = cur + 1;
            }
            if (a > 0 && c > 0) {
                if (distv[a - 1][b + 2][c - 1] > cur + 1)
                    distv[a - 1][b + 2][c - 1] = cur + 1;
            }
            if (b > 0 && c > 0) {
                if (distv[a + 2][b - 1][c - 1] > cur + 1)
                    distv[a + 2][b - 1][c - 1] = cur + 1;
            }
        }

        int ans = INF;
        if (distv[n][0][0] < ans) ans = distv[n][0][0];
        if (distv[0][n][0] < ans) ans = distv[0][n][0];
        if (distv[0][0][n] < ans) ans = distv[0][0][n];

        if (ans == INF) printf("NA\n");
        else printf("%d\n", ans);
    }

    return 0;
}

import sys

def min_time_to_unify(colors, target):
    n = len(colors)
    # Find positions of target color
    pos = [i for i, c in enumerate(colors) if c == target]
    if not pos:
        return None  # impossible
    max_dist = 0
    for i in range(n):
        if colors[i] != target:
            # Find nearest target color position
            # Use binary search for efficiency
            lo, hi = 0, len(pos) - 1
            best = n
            while lo <= hi:
                mid = (lo + hi) // 2
                dist = abs(pos[mid] - i)
                if dist < best:
                    best = dist
                if pos[mid] < i:
                    lo = mid + 1
                else:
                    hi = mid - 1
            if best > max_dist:
                max_dist = best
    return max_dist

