from collections import deque

def next_state(s):
    n = len(s)
    result = list(s)
    colors = {'r', 'g', 'b'}
    for i in range(n):
        left = s[i-1] if i > 0 else None
        right = s[i+1] if i < n-1 else None
        if left is not None and right is not None and left != right:
            # Change to the third color
            result[i] = (colors - {left, right}).pop()
        # else stays the same
    return ''.join(result)

def solve(s):
    if len(set(s)) == 1:
        return 0
    visited = {s: 0}
    queue = deque([s])
    while queue:
        curr = queue.popleft()
        t = visited[curr]
        nxt = next_state(curr)
        if len(set(nxt)) == 1:
            return t + 1
        if nxt not in visited:
            visited[nxt] = t + 1
            queue.append(nxt)
        if nxt == curr:
            # Stuck
            break
    return 'NA'

