public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            String s = sc.next();
            if (s.equals("0")) break;
            int n = s.length();
            // Convert to int array: r=0, g=1, b=2
            int[] start = new int[n];
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (c == 'r') start[i] = 0;
                else if (c == 'g') start[i] = 1;
                else start[i] = 2;
            }
            int ans = Integer.MAX_VALUE;
            for (int target = 0; target < 3; target++) {
                int res = bfs(start, target);
                if (res != -1) ans = Math.min(ans, res);
            }
            if (ans == Integer.MAX_VALUE) System.out.println("NA");
            else System.out.println(ans);
        }
    }

    static int bfs(int[] start, int target) {
        int n = start.length;
        // State encoding: base 3 number
        int startCode = encode(start);
        if (allSame(start, target)) return 0;
        Queue<Integer> q = new LinkedList<>();
        Map<Integer,Integer> dist = new HashMap<>();
        q.add(startCode);
        dist.put(startCode, 0);
        while (!q.isEmpty()) {
            int cur = q.poll();
            int d = dist.get(cur);
            int[] arr = decode(cur, n);
            for (int i = 0; i < n - 1; i++) {
                if (arr[i] != arr[i+1]) {
                    int[] nextArr = arr.clone();
                    int third = 3 - arr[i] - arr[i+1];
                    nextArr[i] = third;
                    nextArr[i+1] = third;
                    int nextCode = encode(nextArr);
                    if (!dist.containsKey(nextCode)) {
                        if (allSame(nextArr, target)) return d + 1;
                        dist.put(nextCode, d + 1);
                        q.add(nextCode);
                    }
                }
            }
        }
        return -1;
    }

    static int encode(int[] arr) {
        int code = 0;
        for (int v : arr) code = code * 3 + v;
        return code;
    }

    static int[] decode(int code, int n) {
        int[] arr = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            arr[i] = code % 3;
            code /= 3;
        }
        return arr;
    }

    static boolean allSame(int[] arr, int target) {
        for (int v : arr) if (v != target) return false;
        return true;
    }
}

