public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("0")) break;
            int n = line.length();
            int[] seg = new int[n];
            for (int i = 0; i < n; i++) {
                char c = line.charAt(i);
                seg[i] = c == 'r' ? 0 : c == 'g' ? 1 : 2;
            }

            // BFS/simulation with cycle detection
            Map<String, Integer> visited = new HashMap<>();
            int[] cur = seg.clone();
            int time = 0;
            boolean found = false;

            while (true) {
                // Check if uniform
                boolean uniform = true;
                for (int i = 1; i < n; i++) if (cur[i] != cur[0]) { uniform = false; break; }
                if (uniform) { System.out.println(time); found = true; break; }

                String key = Arrays.toString(cur);
                if (visited.containsKey(key)) { break; } // cycle, no solution
                visited.put(key, time);

                // Apply rule: new[i] = -(cur[i-1] + cur[i+1]) mod 3, boundaries use only one neighbor
                int[] next = new int[n];
                for (int i = 0; i < n; i++) {
                    int left = (i > 0) ? cur[i-1] : cur[i];
                    int right = (i < n-1) ? cur[i+1] : cur[i];
                    next[i] = (6 - left - right) % 3;
                }
                cur = next;
                time++;
            }

            if (!found) System.out.println("NA");
        }
    }
}

