import java.util.*;

public class Main {
    static final int R = 0, G = 1, B = 2;
    static final int INF = 1 << 28;

    static int color(char c) {
        if (c == 'r') return R;
        if (c == 'g') return G;
        return B;
    }

    static int third(int a, int b) {
        return 3 - a - b; // since colors are 0,1,2
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s;
        StringBuilder out = new StringBuilder();

        while ((s = br.readLine()) != null) {
            s = s.trim();
            if (s.equals("0")) break;
            int n = s.length();

            // dp[l][r][c] = minimum time to make substring [l..r] all color c
            int[][][] dp = new int[n][n][3];
            for (int i = 0; i < n; i++) {
                for (int c = 0; c < 3; c++) dp[i][i][c] = INF;
                dp[i][i][color(s.charAt(i))] = 0;
            }

            for (int len = 2; len <= n; len++) {
                for (int l = 0; l + len - 1 < n; l++) {
                    int r = l + len - 1;
                    for (int c = 0; c < 3; c++) dp[l][r][c] = INF;

                    for (int m = l; m < r; m++) {
                        for (int a = 0; a < 3; a++) {
                            if (dp[l][m][a] >= INF) continue;
                            for (int b = 0; b < 3; b++) {
                                if (dp[m + 1][r][b] >= INF) continue;

                                if (a == b) {
                                    dp[l][r][a] = Math.min(dp[l][r][a],
                                            Math.max(dp[l][m][a], dp[m + 1][r][a]));
                                } else {
                                    int c = third(a, b);
                                    dp[l][r][c] = Math.min(dp[l][r][c],
                                            Math.max(dp[l][m][a], dp[m + 1][r][b]) + 1);
                                }
                            }
                        }
                    }
                }
            }

            int ans = Math.min(dp[0][n - 1][0], Math.min(dp[0][n - 1][1], dp[0][n - 1][2]));
            if (ans >= INF) out.append("NA\n");
            else out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

