string nextState(const string& s) {
    int n = s.size();
    string t = s;
    for (int i = 1; i < n-1; i++) {
        if (s[i-1] == s[i+1] && s[i] != s[i-1]) {
            t[i] = s[i-1];
        }
    }
    return t;
}

bool allSame(const string& s) {
    for (char c : s) if (c != s[0]) return false;
    return true;
}

int main() {
    string s;
    while (cin >> s && s != "0") {
        if (allSame(s)) { cout << 0 << endl; continue; }

        // BFS
        map<string, int> dist;
        queue<string> q;
        dist[s] = 0;
        q.push(s);
        bool found = false;
        while (!q.empty()) {
            string cur = q.front(); q.pop();
            string nxt = nextState(cur);
            if (nxt == cur) {
                // stuck
                break; // can't reach all same
            }
            int d = dist[cur] + 1;
            if (dist.find(nxt) == dist.end()) {
                dist[nxt] = d;
                if (allSame(nxt)) { cout << d << endl; found = true; break; }
                q.push(nxt);
            } else {
                // already visited, cycle detected without solution
                break;
            }
        }
        if (!found) cout << "NA" << endl;
    }
}

