using namespace std;

int solve(const string& s) {
    int n = s.size();

    // Count colors
    bool has_r = false, has_g = false, has_b = false;
    for (char c : s) {
        if (c == 'r') has_r = true;
        if (c == 'g') has_g = true;
        if (c == 'b') has_b = true;
    }

    // If all same color
    if ((has_r && !has_g && !has_b) || (!has_r && has_g && !has_b) || (!has_r && !has_g && has_b)) {
        return 0;
    }

    int ans = INT_MAX;

    // Try each target color
    char targets[] = {'r', 'g', 'b'};
    bool has_target[] = {has_r, has_g, has_b};

    for (int t = 0; t < 3; t++) {
        if (!has_target[t]) continue;
        char target = targets[t];

        // Compute distances from each position to nearest target color
        vector<int> dist_left(n, INT_MAX);
        int last = -1;
        for (int i = 0; i < n; i++) {
            if (s[i] == target) last = i;
            if (last != -1) dist_left[i] = i - last;
        }

        vector<int> dist_right(n, INT_MAX);
        last = -1;
        for (int i = n-1; i >= 0; i--) {
            if (s[i] == target) last = i;
            if (last != -1) dist_right[i] = last - i;
        }

        int max_dist = 0;
        for (int i = 0; i < n; i++) {
            int d = min(dist_left[i], dist_right[i]);
            max_dist = max(max_dist, d);
        }

        ans = min(ans, max_dist);
    }

    return (ans == INT_MAX) ? -1 : ans;
}

int main() {
    string s;
    while (true) {
        cin >> s;
        if (s == "0") break;
        int result = solve(s);
        if (result == -1) {
            cout << "NA" << endl;
        } else {
            cout << result << endl;
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct StateInfo {
    int dist = -1;
    int parent = -1;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Enumerate all strings of length 8 over {r,g,b}.
    // Encode each string as base-3 number in [0, 3^8).
    const int N = 8;
    const int TOT = 6561; // 3^8

    auto encChar = [](char c) -> int {
        if (c == 'r') return 0;
        if (c == 'g') return 1;
        return 2; // 'b'
    };

    auto decode = [&](int mask) {
        array<int, N> a{};
        for (int i = N - 1; i >= 0; --i) {
            a[i] = mask % 3;
            mask /= 3;
        }
        return a;
    };

    auto encode = [&](const array<int, N>& a) -> int {
        int mask = 0;
        for (int i = 0; i < N; ++i) mask = mask * 3 + a[i];
        return mask;
    };

    // Reverse BFS from all monochromatic states.
    vector<int> dist(TOT, -1);
    queue<int> q;

    for (int c = 0; c < 3; ++c) {
        array<int, N> a{};
        for (int i = 0; i < N; ++i) a[i] = c;
        int s = encode(a);
        dist[s] = 0;
        q.push(s);
    }

    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        auto a = decode(cur);

        // Reverse transitions:
        // Forward rule: if adjacent colors x,y are different, both become the third color z.
        // Reverse from current state a:
        // if a[i] == a[i+1] == z, then previous could have had (x,y) or (y,x),
        // where {x,y,z} = {0,1,2}.
        for (int i = 0; i < N - 1; ++i) {
            int z = a[i];
            if (a[i + 1] != z) continue;

            int x = (z + 1) % 3;
            int y = (z + 2) % 3;

            for (int t = 0; t < 2; ++t) {
                array<int, N> pre = a;
                if (t == 0) {
                    pre[i] = x;
                    pre[i + 1] = y;
                } else {
                    pre[i] = y;
                    pre[i + 1] = x;
                }
                int pmask = encode(pre);
                if (dist[pmask] == -1) {
                    dist[pmask] = dist[cur] + 1;
                    q.push(pmask);
                }
            }
        }
    }

    string s;
    while (cin >> s && s != "0") {
        array<int, N> a{};
        for (int i = 0; i < N; ++i) a[i] = encChar(s[i]);
        int mask = encode(a);
        if (dist[mask] == -1) cout << "NA\n";
        else cout << dist[mask] << "\n";
    }

    return 0;
}
